export const ratingLabels=['Rough','Below par','Solid','Great','Excellent'];
export function ratingControls(value,target){return `<fieldset class="rating-field"><legend>How was your workout?</legend><p class="help">Your overall session rating. Optional, and editable later.</p><div class="rating-options">${ratingLabels.map((label,i)=>`<button type="button" data-rating="${i+1}" data-rating-target="${target}" aria-label="${i+1} out of 5 — ${label}" aria-pressed="${value===i+1}" class="${value===i+1?'selected':''}"><span>${i+1}</span><small>${label}</small></button>`).join('')}</div><button class="text-link" data-rating="clear" data-rating-target="${target}">${value?'Clear rating':'Leave unrated'}</button></fieldset>`}
export function ratingBadge(value){return value?`<span class="rating-badge" aria-label="Workout rating ${value} out of 5">★ ${value}/5 · ${ratingLabels[value-1]}</span>`:''}
export function applyAppearance(p){document.documentElement.dataset.appearance=p.appearance;document.documentElement.dataset.accent=p.accent;document.documentElement.dataset.font=p.font;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',p.appearance==='light'?'#f4f3ee':'#111413')}
export function appearanceControls(p){return `<fieldset class="preference-field"><legend>Appearance</legend><div class="segmented">${[['dark','After hours'],['light','Daylight']].map(([id,name])=>`<button data-pref="appearance" data-value="${id}" aria-pressed="${p.appearance===id}" class="${p.appearance===id?'selected':''}">${id==='dark'?'◒':'○'} ${name}</button>`).join('')}</div></fieldset><fieldset class="preference-field"><legend>Accent color</legend><div class="palette">${[['lime','Lime'],['blue','Cobalt'],['rose','Rose'],['amber','Amber']].map(([id,name])=>`<button data-pref="accent" data-value="${id}" aria-label="${name} accent" aria-pressed="${p.accent===id}" class="swatch ${id} ${p.accent===id?'selected':''}"><i aria-hidden="true"></i><span>${name}</span>${p.accent===id?'<b aria-hidden="true">✓</b>':''}</button>`).join('')}</div></fieldset><fieldset class="preference-field"><legend>Typography</legend><div class="font-options">${[['space','Space Grotesk','A little more character.'],['manrope','Manrope','Rounded. Calm. Precise.']].map(([id,name,desc])=>`<button data-pref="font" data-value="${id}" aria-pressed="${p.font===id}" class="font-card ${id} ${p.font===id?'selected':''}"><span class="font-sample">Aa 012</span><strong>${name}</strong><small>${desc}</small></button>`).join('')}</div></fieldset>`}
export function setupView(p){return `<section class="onboarding"><p class="eyebrow">WELCOME TO SETLINE</p><h1>Your training.<br>Your way.</h1><p class="muted">A few things to make this log feel like yours. You can change everything in Settings.</p><div class="setup-basics"><label for="setup-unit">Weight unit<select id="setup-unit" data-pref="unit"><option value="kg" ${p.unit==='kg'?'selected':''}>Kilograms (kg)</option><option value="lb" ${p.unit==='lb'?'selected':''}>Pounds (lb)</option></select></label><label for="setup-rest">Rest between sets<select id="setup-rest" data-pref="rest">${[[0,'Off'],[30,'30 seconds'],[60,'1 minute'],[90,'90 seconds'],[120,'2 minutes'],[180,'3 minutes'],[300,'5 minutes']].map(([n,label])=>`<option value="${n}" ${p.rest===n?'selected':''}>${label}</option>`).join('')}</select></label></div>${appearanceControls(p)}<fieldset class="preference-field"><legend>Usual training days <span class="muted">· optional</span></legend><div class="day-options">${[1,2,3,4,5,6,0].map(i=>`<button data-setup-day="${i}" aria-label="${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][i]}" aria-pressed="${p.schedule.includes(i)}" class="${p.schedule.includes(i)?'selected':''}">${['Su','Mo','Tu','We','Th','Fr','Sa'][i]}</button>`).join('')}</div><p class="help">Used to show planned and missed days on your activity calendar.</p></fieldset><button class="primary wide" data-action="complete-setup">Let’s train</button><button class="text-link wide" data-action="import">Already have a backup? Restore it</button><input id="import-file" type="file" accept="application/json,.json" hidden><p class="setup-privacy">Saved on this device. No account needed.</p></section>`}
